def pt_in_tri(x,y,t):
    # barycentric area signs
    p=np.array([x,y]);
    def cr(a,b,c): return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])
    vals=[cr(t[i],t[(i+1)%3],p) for i in range(3)]
    return all(v>=-1e-9 for v in vals) or all(v<=1e-9 for v in vals)
